class Solution:
    def waysToBuyPensPencils(self, total: int, cost1: int, cost2: int) -> int:
        dp = [1] + [0] * total
        for c in (cost1, cost2):
            for s in range(c, total + 1):
                dp[s] += dp[s - c]
        return sum(dp)

