class Solution {
public:
    long long waysToBuyPensPencils(int total, int cost1, int cost2) {
        vector<long long> dp(total + 1, 0);
        dp[0] = 1;
        for (int c : {cost1, cost2}) {
            for (int s = c; s <= total; s++) {
                dp[s] += dp[s - c];
            }
        }
        long long ans = 0;
        for (long long w : dp) ans += w;
        return ans;
    }
};

